command:
sudo -n sh -c "cat > /etc/nginx/conf.d/port-6500.conf <<'ANTRIEB_EOF'
server {
    listen 6500 default_server;
    listen [::]:6500 default_server;
    server_name _;

    location = / {
        default_type text/plain;
        return 200 'nginx on port 6500\n';
    }
}
ANTRIEB_EOF
"
sudo -n nginx -t
sudo -n cat /etc/nginx/conf.d/port-6500.conf

